// DeleteOne permanently deletes a single Tasting record by ID
func (r *TastingRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	query := `DELETE FROM tasting WHERE id = $1`

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, id.ToUUID())
	} else {
		result, err = r.db.pool.Exec(ctx, query, id.ToUUID())
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}

// DeleteOneIfVersion permanently deletes a single Tasting only if its
// current _version matches expectedVersion. It returns ErrVersionConflict when
// the row exists at another version and ErrNotFound when it does not exist.
func (r *TastingRepository) DeleteOneIfVersion(ctx context.Context, id types.IdentityUUID, expectedVersion int64) error {
	query := `DELETE FROM tasting WHERE id = $1 AND _version = $2`
	queryArgs := []interface{}{id.ToUUID(), expectedVersion}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return r.versionMiss(ctx, id)
	}

	return nil
}

// DeleteMany permanently deletes multiple Tasting records matching the filter
func (r *TastingRepository) DeleteMany(ctx context.Context, filter *TastingFilter) (int, error) {
	// Build WHERE clause
	var values []interface{}
	whereClause := filter.buildWhereClause(&values, 0)

	query := fmt.Sprintf(`DELETE FROM tasting%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}
